// Нативный сценарий (в web нет): после включения «תזכורות במערכת» приложение запрашивает разрешение на уведомления (системный диалог).
// Опора: постановка задачи регресса приложения; текст тумблера «כולל התראות ל: זמני תפילה, תפילין, ספירת העומר, ראש חודש ומועדים» (RM-03).
// @manual-check: системный диалог показывается ОС только пока разрешение «не определено» (первый запрос после установки).
//   Android: в wdio.conf.ts autoGrantPermissions=true — разрешение выдаётся при установке, диалога не будет;
//   iOS: autoAcceptAlerts=false — диалог виден, но только на свежей установке (или после сброса разрешений в Настройках).
//   Поэтому авто-проверка: если диалог появился — проверить и нажать «Разрешить»; если нет — тумблер включён и сохранён,
//   а сам запрос проверяется вручную на чистой установке (Android — без autoGrantPermissions).
import { $, expect, driver } from '@wdio/globals';
import { byText, byLabelStartsWith, tapLabel, expectTextContains, scrollToText } from '../../helpers/ui.ts';
import { toHome } from '../../helpers/app.ts';
/** Минимальный тип элемента (подходит и для WebdriverIO.Element, и для ChainablePromiseElement). */
type El = {
  getAttribute(name: string): Promise<string | null>;
  isSelected(): Promise<boolean>;
  getLocation(): Promise<{ x: number; y: number }>;
  getSize(): Promise<{ width: number; height: number }>;
};

async function isOn(el: El) {
  if (driver.isAndroid) return (await el.getAttribute('checked')) === 'true';
  const v = await el.getAttribute('value');
  return v === '1' || v === 'true';
}
async function reminderSwitch() {
  await scrollToText('תזכורות והתראות');
  const sw = await byLabelStartsWith('תזכורות והתראות');
  await sw.waitForDisplayed();
  return sw;
}

/** Ждать системный запрос уведомлений до 10 с. Возвращает текст диалога или null. */
async function waitPermissionDialog(): Promise<string | null> {
  let text: string | null = null;
  await driver
    .waitUntil(
      async () => {
        if (driver.isAndroid) {
          const allow = await $('android=new UiSelector().resourceIdMatches(".*permission_allow_button.*")');
          if (!(await allow.isDisplayed().catch(() => false))) return false;
          const msg = await $('android=new UiSelector().resourceIdMatches(".*permission_message.*")');
          text = (await msg.getText().catch(() => '')) || 'android-permission';
          return true;
        }
        text = await driver.getAlertText().catch(() => null);
        return Boolean(text);
      },
      { timeout: 10000, interval: 500 },
    )
    .catch(() => {});
  return text;
}

async function allowPermission() {
  if (driver.isAndroid) await (await $('android=new UiSelector().resourceIdMatches(".*permission_allow_button.*")')).click();
  else await driver.acceptAlert();
}

describe('Напоминания — разрешение на уведомления', () => {
  afterEach(async () => { await toHome(); });

  it('RM-PUSH Включение «תזכורות והתראות» запрашивает разрешение на уведомления устройства @data @manual-check', async () => {
    await toHome();
    await tapLabel('מעבר לפרטים שלי');
    await (await byText('פרופיל אישי')).waitForDisplayed({ timeout: 20000 });

    // Исходно тумблер включён (как в RM-02): выключить, чтобы проверить именно включение.
    let sw = await reminderSwitch();
    if (await isOn(sw)) {
      await sw.click();
      await expectTextContains('תזכורות והתראות: השינוי נשמר.');
      await driver.waitUntil(async () => !(await isOn(await byLabelStartsWith('תזכורות והתראות'))));
    }

    // Включить → системный запрос уведомлений (если ОС ещё не знает ответа).
    sw = await byLabelStartsWith('תזכורות והתראות');
    await sw.click();
    const dialog = await waitPermissionDialog();
    if (dialog) {
      if (!driver.isAndroid) expect(dialog).toMatch(/Notifications|התראות|уведомлен/i);
      await allowPermission();
    } else {
      console.warn('[RM-PUSH] системный диалог не появился (разрешение уже определено) — проверить вручную на чистой установке');
    }

    // Итог: тумблер включён и сохранён — исходное состояние восстановлено.
    await expectTextContains('תזכורות והתראות: השינוי נשמר.');
    await driver.waitUntil(async () => isOn(await byLabelStartsWith('תזכורות והתראות')), { timeoutMsg: 'тумблер не включился' });
  });
});
